function chain(){const j=journey();$("#energy-chain").innerHTML=j.stages.map((id,i)=>{const t=tops.find(x=>x.id===id),c=C[id]||B,kind=c.role?.includes("关键")||c.role?.includes("输入端")||id==="flyback"?"tvs":c.role?.includes("不用")||c.role?.includes("不是")?"no":"coord";return`<button class="chain-node ${kind} ${i===active?'active':''}" data-stage="${i}"><span class="mark"></span><b>${t?.name||id}</b><small>${t?.voltage||''}</small></button>`}).join("")+`<div class="chain-node no"><span class="mark"></span><b>${j.end}</b><small>客户最终负载</small></div>`;$$('[data-stage]').forEach(b=>b.onclick=()=>{active=+b.dataset.stage;focus()});$("#chain-insight").innerHTML=`<b>这一站的判断：</b><span>${info().insight}</span>`}
